import{_ as l,I as t,o as n,c as d,b6 as e,j as h,J as i,w as o}from"./chunks/framework.COUcLbTA.js";const y=JSON.parse('{"title":"生鲜电商微服务系统开发实战","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"zh-cn/stage-2/assignments/simple-grocery-microservices/index.md"}'),c={name:"zh-cn/stage-2/assignments/simple-grocery-microservices/index.md"},p={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const r=t("StepBar"),s=t("ClientOnly");return n(),d("div",null,[a[0]||(a[0]=e('<h1 id="生鲜电商微服务系统开发实战" tabindex="-1">生鲜电商微服务系统开发实战 <a class="header-anchor" href="#生鲜电商微服务系统开发实战" aria-label="Permalink to “生鲜电商微服务系统开发实战”">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>本实战项目要求你围绕一份真实的 PRD，从零完成一个生鲜电商微服务系统。与前面的单服务项目不同，这个项目的后端按业务拆分成多个独立服务，通过 API 网关统一对外。你将学习如何设计服务边界、如何处理跨服务的数据一致性问题。</p><p>这是 Stage 2 的综合实战环节。微服务架构在实际工作中非常常见，掌握服务拆分和网关路由的基本思路后，你能够应对更复杂的后端系统设计。</p><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to “前置知识”">​</a></h2><p>在开始本项目之前，你应该已经掌握以下内容：</p><ul><li>前端页面设计与组件库使用（<a href="./../../frontend/ui-design/">UI 设计</a>、<a href="./../../frontend/modern-component-library/">现代组件库</a>）</li><li>后端接口设计与开发（<a href="./../../backend/ai-interface-code/">接口代码编写</a>）</li><li>数据库基础与 Supabase（<a href="./../../backend/database-supabase/">从数据库到 Supabase</a>）</li><li>Git 工作流与部署（<a href="./../../backend/git-workflow/">Git 和 GitHub</a>、<a href="./../../backend/zeabur-deployment/">部署 Web 应用</a>）</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to “学习目标”">​</a></h2><p>完成本实战后，你将能够：</p><ol><li>阅读 PRD 并提取微服务系统的开发任务清单</li><li>按业务领域拆分服务边界（鉴权、商品、库存、订单）</li><li>设计和实现 API 网关路由</li><li>处理库存扣减和订单一致性等跨服务问题</li><li>完成端到端联调，交付可演示的微服务原型</li></ol><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to “项目简介”">​</a></h2><p>你要构建的产品是一个生鲜电商微服务系统：</p><table tabindex="0"><thead><tr><th>子系统</th><th>职责</th></tr></thead><tbody><tr><td><strong>用户端</strong></td><td>浏览商品、下单、查看订单</td></tr><tr><td><strong>管理端</strong></td><td>商品管理、库存管理、订单管理</td></tr></tbody></table><p>后端按业务拆分为以下服务：</p><table tabindex="0"><thead><tr><th>服务</th><th>职责</th></tr></thead><tbody><tr><td><strong>API Gateway</strong></td><td>统一入口、路由转发、鉴权校验</td></tr><tr><td><strong>Auth Service</strong></td><td>用户注册、登录、JWT 颁发</td></tr><tr><td><strong>Catalog Service</strong></td><td>商品信息管理</td></tr><tr><td><strong>Inventory Service</strong></td><td>库存数量管理</td></tr><tr><td><strong>Order Service</strong></td><td>订单创建、状态管理</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">PRD 入口</p><p>本项目的需求文档在 GitHub： <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">查看 PRD</a></p></div>',16)),h("div",p,[i(s,null,{default:o(()=>[i(r,{active:0,items:[{title:"需求分析",description:"阅读 PRD，明确服务拆分、页面和交易链路"},{title:"搭建骨架",description:"生成前端、网关和各服务骨架"},{title:"迭代开发",description:"逐模块补接口、修库存与订单一致性"},{title:"联调上线",description:"端到端跑通，部署并准备演示"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="第一部分-需求分析" tabindex="-1">第一部分：需求分析 <a class="header-anchor" href="#第一部分-需求分析" aria-label="Permalink to “第一部分：需求分析”">​</a></h2><h3 id="_1-1-阅读-prd" tabindex="-1">1.1 阅读 PRD <a class="header-anchor" href="#_1-1-阅读-prd" aria-label="Permalink to “1.1 阅读 PRD”">​</a></h3><p>打开 PRD 文档，重点回答以下问题：</p><ul><li>服务如何拆分？每个服务的职责边界是什么？</li><li>前台和管理端分别有哪些页面？</li><li>下单后库存扣减的策略是什么？成功 / 失败 / 超时各怎么处理？</li><li>第一版哪些复杂能力（如分布式事务、消息队列）先不做？</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>如果以上问题没有明确答案，不要开始写代码。需求理解不清楚是导致返工的最常见原因。</p></div><h3 id="_1-2-确认系统架构" tabindex="-1">1.2 确认系统架构 <a class="header-anchor" href="#_1-2-确认系统架构" aria-label="Permalink to “1.2 确认系统架构”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; fe[&quot;前端页面&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fe --&gt; gw[&quot;API Gateway&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; auth[&quot;Auth Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; catalog[&quot;Catalog Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; inventory[&quot;Inventory Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; order[&quot;Order Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; inventory</span></span></code></pre></div><h2 id="第二部分-搭建项目骨架" tabindex="-1">第二部分：搭建项目骨架 <a class="header-anchor" href="#第二部分-搭建项目骨架" aria-label="Permalink to “第二部分：搭建项目骨架”">​</a></h2><h3 id="_2-1-生成项目结构" tabindex="-1">2.1 生成项目结构 <a class="header-anchor" href="#_2-1-生成项目结构" aria-label="Permalink to “2.1 生成项目结构”">​</a></h3><p>提示词参考：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请基于当前 PRD，帮我生成一个生鲜电商微服务系统的项目骨架。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 生成前端用户端和管理端骨架</span></span>
<span class="line"><span>2. 生成 api-gateway、auth-service、catalog-service、inventory-service、order-service 五个目录</span></span>
<span class="line"><span>3. 每个服务先只做最小可运行入口</span></span>
<span class="line"><span>4. 先不接真实数据库和支付</span></span></code></pre></div><h3 id="_2-2-验证项目结构" tabindex="-1">2.2 验证项目结构 <a class="header-anchor" href="#_2-2-验证项目结构" aria-label="Permalink to “2.2 验证项目结构”">​</a></h3><p>逐项检查：</p><ul><li>[ ] 五个服务目录结构清晰</li><li>[ ] API Gateway 可以启动并转发请求</li><li>[ ] 各服务健康检查接口可用</li><li>[ ] 前端用户端和管理端页面可访问</li></ul><h2 id="第三部分-迭代开发" tabindex="-1">第三部分：迭代开发 <a class="header-anchor" href="#第三部分-迭代开发" aria-label="Permalink to “第三部分：迭代开发”">​</a></h2><h3 id="_3-1-按模块推进" tabindex="-1">3.1 按模块推进 <a class="header-anchor" href="#_3-1-按模块推进" aria-label="Permalink to “3.1 按模块推进”">​</a></h3><ol><li><strong>API Gateway</strong>：路由配置、JWT 校验中间件</li><li><strong>Auth Service</strong>：注册、登录、JWT 颁发</li><li><strong>Catalog Service</strong>：商品 CRUD、列表查询</li><li><strong>Inventory Service</strong>：库存查询、库存扣减</li><li><strong>Order Service</strong>：订单创建、状态流转、库存联动</li><li><strong>管理端</strong>：商品管理、库存管理、订单管理</li></ol><h3 id="_3-2-模块自检" tabindex="-1">3.2 模块自检 <a class="header-anchor" href="#_3-2-模块自检" aria-label="Permalink to “3.2 模块自检”">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>验证方法</th></tr></thead><tbody><tr><td>网关路由</td><td>各服务接口是否通过网关正确转发</td></tr><tr><td>权限隔离</td><td>用户端和管理端接口是否隔离</td></tr><tr><td>数据一致</td><td>商品和库存数据是否同步</td></tr><tr><td>交易闭环</td><td>下单后库存扣减、订单状态是否一致</td></tr><tr><td>失败处理</td><td>库存不足或超时时是否有补偿机制</td></tr></tbody></table><h2 id="第四部分-联调与上线" tabindex="-1">第四部分：联调与上线 <a class="header-anchor" href="#第四部分-联调与上线" aria-label="Permalink to “第四部分：联调与上线”">​</a></h2><h3 id="_4-1-端到端测试" tabindex="-1">4.1 端到端测试 <a class="header-anchor" href="#_4-1-端到端测试" aria-label="Permalink to “4.1 端到端测试”">​</a></h3><p>至少验证以下场景：</p><ul><li>浏览商品 → 加入购物车 → 下单 → 查看订单</li><li>管理员 → 添加商品 → 更新库存 → 查看订单</li></ul><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to “交付物”">​</a></h2><p>完成本项目后，你需要提交以下内容：</p><ul><li>[ ] 可访问的线上演示链接</li><li>[ ] 源码仓库链接（含 README）</li><li>[ ] PRD 文档</li><li>[ ] 核心页面截图（商品列表、下单页、订单页、管理后台）</li><li>[ ] 60 秒演示视频</li></ul><h2 id="评分标准" tabindex="-1">评分标准 <a class="header-anchor" href="#评分标准" aria-label="Permalink to “评分标准”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>基本要求</th><th>进阶要求</th></tr></thead><tbody><tr><td>PRD 对齐</td><td>页面、功能、服务拆分基本符合 PRD</td><td>能清晰说明服务拆分的理由</td></tr><tr><td>产品闭环</td><td>浏览 → 下单 → 库存扣减 → 查看订单可跑通</td><td>订单超时或库存不足有补偿机制</td></tr><tr><td>服务架构</td><td>各服务可独立启动，通过网关统一访问</td><td>服务间通信有错误处理和重试</td></tr><tr><td>后台能力</td><td>商品、库存、订单管理可操作</td><td>管理端有数据统计</td></tr><tr><td>工程完整度</td><td>前端、网关、服务、数据库链路已接通</td><td>有 Docker Compose 或类似编排</td></tr></tbody></table><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">UI 设计</a></li><li><a href="./../../frontend/modern-component-library/">使用现代组件库更新你的界面</a></li><li><a href="./../../backend/database-supabase/">从数据库到 Supabase</a></li><li><a href="./../../backend/ai-interface-code/">大模型辅助编写接口代码与接口文档</a></li><li><a href="./../../backend/git-workflow/">Git 和 GitHub 工作流</a></li><li><a href="./../../backend/zeabur-deployment/">如何部署 Web 应用</a></li></ul>`,30))])}const P=l(c,[["render",b]]);export{y as __pageData,P as default};
